<?php
declare(strict_types=1);
require dirname(__DIR__).'/backend/inventory/src/bootstrap.php';require dirname(__DIR__).'/backend/inventory/src/itsm-auth.php';require dirname(__DIR__).'/backend/inventory/src/nav.php';require dirname(__DIR__).'/backend/inventory/src/InventoryV2.php';require dirname(__DIR__).'/backend/inventory/src/V2Licensing.php';require dirname(__DIR__).'/backend/inventory/src/V2Reports.php';
try{
 $actor=inventoryActor(true);
 webHeaders(true);
 if(getenv('INV_ENABLED')!=='1')respond(503,['error'=>'inventory_disabled']);if(!enabled())respond(503,['error'=>'inventory_disabled']);
 $view=$_GET['view']??'overview';if(!is_string($view)||!in_array($view,['overview','changes','licenses','security','reports','notifications','settings'],true))throw new InvalidArgumentException();
 $manage=v2Manage($actor);$master=v2Enabled(db());$features=[];foreach(V2_FEATURES as $feature)$features[$feature]=v2Enabled(db(),$feature);
 if(!$master&&!($view==='settings'&&$actor['admin']))respond(503,['error'=>'v2_disabled']);
 if($view==='settings'&&!$actor['admin'])respond(403,['error'=>'admin_required']);
 if($view==='licenses'&&!$manage)respond(403,['error'=>'license_access_denied']);
 if(isset($features[$view])&&!$features[$view])respond(503,['error'=>'feature_disabled']);
 $customers=inventoryCustomers($actor);$customerNames=[];foreach($customers as $c)$customerNames[(int)$c['id']]=$c['name'];$f=v2Filters($_GET);
 if($master)v2EvaluateThrottled(db());
 $report=$view==='reports'?($_GET['report']??'computers'):(in_array($view,['changes','security'],true)?$view:'computers');
 if(!is_string($report)||!in_array($report,V2_REPORTS,true))throw new InvalidArgumentException();
 if(in_array($view,['changes','security','reports'],true)){$columns=v2ReportColumns($report);$records=v2Report(db(),$actor,$report,$f,51,($f['page']-1)*50);$more=count($records)>50;$records=array_slice($records,0,50);}
 $event=null;
 if(isset($_GET['event'])){if($view!=='changes'||!is_string($_GET['event'])||!preg_match('/^[a-f0-9]{64}$/D',$_GET['event']))throw new InvalidArgumentException();[$where,$params]=inventoryScope($actor);$q=db()->prepare('SELECT e.*,c.hostname FROM inv_v2_events e JOIN inv_agents a ON a.id=e.agent_id JOIN inv_computers c ON c.agent_id=a.id WHERE '.$where.' AND e.event_key=?');$q->execute([...$params,$_GET['event']]);$event=$q->fetch();if(!$event)respond(404,['error'=>'not_found']);}
 if($view==='overview'){
  [$where,$params]=inventoryScope($actor);$q=db()->prepare('SELECT COUNT(*) AS computers,SUM(a.last_seen>=UTC_TIMESTAMP() - INTERVAL 2 DAY) AS recent FROM inv_computers c JOIN inv_agents a ON a.id=c.agent_id WHERE '.$where);$q->execute($params);$overview=$q->fetch();
  [$where,$params]=v2Tenant($actor,'customer_id');$q=db()->prepare("SELECT COUNT(*) FROM inv_v2_notices WHERE ".$where." AND active=1 AND acknowledged_at IS NULL".($manage?'':" AND kind NOT IN ('license_expiry','license_capacity')"));$q->execute($params);$openNotices=(int)$q->fetchColumn();
 }
 if($view==='licenses'){
  [$where,$params]=v2Tenant($actor,'p.customer_id');$q=db()->prepare('SELECT p.*,(SELECT COUNT(DISTINCT i.agent_id) FROM inv_v2_installations i JOIN inv_agents a ON a.id=i.agent_id WHERE a.customer_id=p.customer_id AND i.name_hash=p.name_hash AND (p.publisher_hash=\'\' OR i.publisher_hash=p.publisher_hash)) AS installed_devices FROM inv_v2_products p WHERE '.$where.' ORDER BY p.name,p.id LIMIT 501');$q->execute($params);$products=$q->fetchAll();$productsLimited=count($products)>500;$products=array_slice($products,0,500);
  $entitlements=v2Report(db(),$actor,'licenses',$f,501);$entitlementsLimited=count($entitlements)>500;$entitlements=array_slice($entitlements,0,500);
  [$where,$params]=v2Tenant($actor,'x.customer_id');$q=db()->prepare('SELECT x.*,p.name,e.metric FROM inv_v2_assignments x JOIN inv_v2_entitlements e ON e.id=x.entitlement_id JOIN inv_v2_products p ON p.id=e.product_id WHERE '.$where.' AND x.active=1 ORDER BY p.name,x.id LIMIT 501');$q->execute($params);$assignments=$q->fetchAll();$assignmentsLimited=count($assignments)>500;$assignments=array_slice($assignments,0,500);
  [$where,$params]=inventoryScope($actor);$q=db()->prepare('SELECT c.agent_id,c.hostname,a.customer_id FROM inv_computers c JOIN inv_agents a ON a.id=c.agent_id WHERE '.$where.' AND a.enabled=1 ORDER BY c.hostname LIMIT 2000');$q->execute($params);$devices=$q->fetchAll();
 }
 if($view==='notifications'){
  [$where,$params]=v2Tenant($actor,'n.customer_id');$resolved=($_GET['resolved']??'')==='1';$q=db()->prepare('SELECT n.*,c.hostname FROM inv_v2_notices n LEFT JOIN inv_computers c ON c.agent_id=n.agent_id WHERE '.$where.' AND n.active=?'.($manage?'':" AND n.kind NOT IN ('license_expiry','license_capacity')").' ORDER BY n.last_seen DESC,n.id DESC LIMIT 101 OFFSET '.(($f['page']-1)*100));$q->execute([...$params,$resolved?0:1]);$notices=$q->fetchAll();$more=count($notices)>100;$notices=array_slice($notices,0,100);
 }
}catch(InvalidArgumentException){respond(400,['error'=>'invalid_v2_filters']);}
catch(DomainException){respond(403,['error'=>'v2_access_denied']);}
catch(Throwable $e){error_log('Inventory V2 dashboard failure: '.get_class($e));respond(503,['error'=>'v2_unavailable']);}
function h(mixed $v):string{return htmlspecialchars(is_scalar($v)?(string)$v:json_encode($v,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function url(array $replace=[]):string{return '?'.http_build_query(array_replace($_GET,$replace));}
function postFields(string $action,?int $id=null):void{global $actor;echo '<input type="hidden" name="csrf_token" value="'.h($actor['csrf_token']).'"><input type="hidden" name="action" value="'.h($action).'">';if($id!==null)echo '<input type="hidden" name="id" value="'.h($id).'">';}
function formInput(string $name,string $label,string $type='text',mixed $value='',bool $required=false):void{echo '<label>'.h($label).'<input name="'.h($name).'" type="'.h($type).'" value="'.h($value??'').'" '.($required?'required':'').' '.($type==='text'?'maxlength="255"':'').($type==='number'?' min="1" max="1000000000"':'').'></label>';}
function metricSelect(string $metric='device'):void{echo '<label>Måleenhed<select name="metric"><option value="device" '.($metric==='device'?'selected':'').'>Pr. enhed</option><option value="user" '.($metric==='user'?'selected':'').'>Pr. bruger</option></select></label>';}
$titles=['overview'=>'Version 2 · overblik','changes'=>'Detaljeret ændringshistorik','licenses'=>'Licensadministration','security'=>'Sikkerhedsstatus','reports'=>'Rapporter og eksport','notifications'=>'Notifikationer','settings'=>'Modulindstillinger'];
?><!doctype html><html lang="da"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>PC Inventory Agent · <?=h($titles[$view])?></title><link rel="stylesheet" href="inventory.css?v=<?=h(substr(hash_file('sha256',__DIR__.'/inventory.css'),0,12))?>"></head><body><main>
<?php invNav($actor, isset($customers) ? $customers : [], isset($filters['customer']) ? (int)$filters['customer'] : 0, 'history'); ?>
<nav aria-label="Version 2"><?php foreach($titles as $key=>$title):if(($key==='settings'&&!$actor['admin'])||($key==='licenses'&&!$manage)||(isset($features[$key])&&!$features[$key]))continue;?><a href="?view=<?=h($key)?>" <?=$view===$key?'aria-current="page"':''?>><?=h($title)?></a><?php endforeach ?></nav>
<h1><?=h($titles[$view])?></h1><p>Adgang følger ITSM-kunder og roller. Alle måle- og hændelsestider vises i UTC.</p>
<?php if(($_GET['saved']??'')==='1'):?><p role="status" class="ok">Ændringen er gemt.</p><?php endif ?>
<?php if($view==='overview'):?>
<section class="stats"><article><strong><?=h((int)$overview['computers'])?></strong><span>Tilgængelige computere</span></article><article><strong><?=h((int)$overview['recent'])?></strong><span>Kontakt inden for 48 timer</span></article><article><strong><?=h($openNotices)?></strong><span>Aktive, ikke kvitterede notifikationer</span></article></section>
<section class="panel"><h2>Version 2 er aktiv</h2><p>Detaljerede hændelser registreres ved nye scanninger. Eksisterende version 1-agenter fortsætter; sikkerhed og aktivering vises som ukendt, indtil en version 2-agent har sendt oplysningerne.</p><p>Licensbeholdning registreres centralt og sammenholdes med det senest kendte softwareinventar. Automatisk aktiveringsstatus dokumenterer ikke virksomhedens licensret.</p><p>Notifikationer vises her i ITSM. Der sendes ingen e-mails. Regler genberegnes ved scanninger og ved åbning af version 2, højst én gang hvert femte minut.</p></section>
<?php endif ?>
<?php if(in_array($view,['changes','security','reports'],true)):?>
<form method="get" class="list-controls"><input type="hidden" name="view" value="<?=h($view)?>">
<?php if($view==='reports'):?><label>Rapport<select name="report"><?php foreach(V2_REPORTS as $r):if((in_array($r,['licenses','activations'],true)&&(!$manage||!$features['licenses']))||($r==='security'&&!$features['security'])||($r==='changes'&&!$features['changes']))continue;?><option value="<?=h($r)?>" <?=$r===$report?'selected':''?>><?=h(['computers'=>'Computere','software'=>'Software','security'=>'Sikkerhed','changes'=>'Ændringer','licenses'=>'Licenser','activations'=>'Aktiveringsobservationer'][$r])?></option><?php endforeach ?></select></label><?php endif ?>
<label>Søg<input name="q" maxlength="250" value="<?=h($f['q'])?>" type="search" placeholder="Computer, produkt eller element"></label><label>Kunde<select name="customer"><option value="">Alle tilgængelige</option><?php foreach($customers as $c):?><option value="<?=h($c['id'])?>" <?=(string)$c['id']===$f['customer']?'selected':''?>><?=h($c['name'])?></option><?php endforeach ?></select></label>
<?php if($f['agent']!==''):?><input type="hidden" name="agent" value="<?=h($f['agent'])?>"><?php endif ?>
<?php if($report==='changes'):?><?php formInput('from','Fra','date',$f['from']);formInput('to','Til','date',$f['to']);?><label>Kategori<select name="category"><option value="">Alle</option><?php foreach(['software','hardware','computer','disks','network','network_config','security','collection'] as $k):?><option value="<?=h($k)?>" <?=$k===$f['category']?'selected':''?>><?=h($k)?></option><?php endforeach ?></select></label><?php endif ?>
<?php if($report==='security'):?><label>Status eller aktualitet<select name="state"><option value="">Alle</option><?php foreach(['enabled','disabled','unknown','not_supported','attention','current','stale','not_received'] as $k):?><option value="<?=h($k)?>" <?=$k===$f['state']?'selected':''?>><?=h(v2Label($k))?></option><?php endforeach ?></select></label><?php endif ?><button type="submit">Søg og filtrér</button></form>
<?php if($features['reports']):?><div class="group-actions"><?php foreach(['xlsx'=>'Excel (.xlsx)','csv'=>'CSV'] as $format=>$label):?><a href="v2-export.php?<?=h(http_build_query(array_merge($f,['report'=>$report,'format'=>$format])))?>">Hent <?=h($label)?></a><?php endforeach ?></div><p>Eksporten omfatter alle matchende rækker, højst 10.000. Ved flere rækker skal filtrene indsnævres.</p><?php endif ?>
<section class="panel"><div class="table-scroll"><table><thead><tr><?php foreach($columns as $column):?><th><?php if(isset(v2Sortables($report)[$column])):?><a href="<?=h(url(['sort'=>$column,'direction'=>$f['sort']===$column&&$f['direction']==='asc'?'desc':'asc','page'=>1]))?>"><?=h(v2Label($column))?> ↕</a><?php else:?><?=h(v2Label($column))?><?php endif ?></th><?php endforeach ?></tr></thead><tbody><?php foreach($records as $row):?><tr><?php foreach($columns as $column):?><td><?php if($report==='changes'&&$column==='label'):?><a href="<?=h(url(['event'=>$row['event_key']]))?>"><?=h($row['category']==='software'?$row[$column]:v2Label($row[$column]))?></a><?php else:?><?=h(in_array($column,['operation','state','check_name','freshness','metric','source','category'],true)?v2Label((string)($row[$column]??'')):($row[$column]??'Ukendt'))?><?php endif ?></td><?php endforeach ?></tr><?php endforeach ?><?php if(!$records):?><tr><td colspan="<?=count($columns)?>">Ingen matchende oplysninger. Version 2-data indsamles fra næste scanning.</td></tr><?php endif ?></tbody></table></div></section>
<nav class="pagination"><?php if($f['page']>1):?><a href="<?=h(url(['page'=>$f['page']-1,'event'=>null]))?>">← Forrige</a><?php endif ?><span>Side <?=h($f['page'])?></span><?php if($more):?><a href="<?=h(url(['page'=>$f['page']+1,'event'=>null]))?>">Næste →</a><?php endif ?></nav>
<?php if($event):?><details class="panel" open><summary><?=h($event['hostname'].' · '.$event['label'].' · '.$event['occurred_at'])?></summary><h2>Før</h2><pre><?=h(json_encode(json_decode($event['before_value'],true),JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE))?></pre><h2>Efter</h2><pre><?=h(json_encode(json_decode($event['after_value'],true),JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE))?></pre></details><?php endif ?>
<?php if($report==='activations'):?><p>Windows-aktivering indsamles via SoftwareLicensingProduct. Først observeret aktiveret er den første scanning, der viste aktiveret status, og er ikke den oprindelige aktiveringsdato. Evalueringsudløb gælder evalueringsprodukter; resterende aktiveringsfrist er et øjebliksbillede og kan for KMS betyde tid til genaktivering. Tomme felter betyder ikke oplyst. macOS og Linux har ingen fælles kilde til programlicenser. Dette er kun observeret produktaktivering. En aktivering dokumenterer ikke købte licensrettigheder, Microsoft 365-tildeling eller compliance.</p><?php endif ?>
<?php if($report==='security'):?><p>Ukendt, ikke understøttet og forældet måling betyder ikke sikker. FileVault-/BitLocker-status omfatter den angivne platformskontrol, ikke en revision af alle diske. Opdateringsaktualitet og leverandørspecifik EDR vises som ikke vurderet, hvor der mangler en pålidelig datakilde.</p><?php endif ?>
<?php endif ?>
<?php if($view==='licenses')require dirname(__DIR__).'/backend/inventory/src/v2-license-panel.php'; ?>
<?php if($view==='notifications'):?>
<p>Regler: under 10 % ledig diskplads, agent uden kontakt i 48 timer, målt deaktiveret beskyttelse, inventarændringer inden for 24 timer, licensudløb inden for 30 dage og flere tildelinger end registrerede pladser. Kvittering markerer en notifikation set; den ændrer ikke enhedens tilstand.</p><a href="<?=h(url(['resolved'=>$resolved?'0':'1','page'=>1]))?>"><?=$resolved?'Vis aktive':'Vis afsluttede'?> notifikationer</a>
<?php foreach($notices as $notice):?><article class="panel"><h2><?=h($notice['title'])?></h2><p><?=h($notice['message'])?></p><p><?=h($customerNames[(int)$notice['customer_id']]??$notice['customer_id'])?> · <?=h(['info'=>'Information','warning'=>'Advarsel','critical'=>'Kritisk'][$notice['severity']]??$notice['severity'])?> · senest observeret <?=h($notice['last_seen'])?> UTC</p><?php if($notice['agent_id']):?><a href="./?id=<?=h($notice['agent_id'])?>">Se computer</a><?php endif ?><?php if($notice['acknowledged_at']):?><p>Kvitteret <?=h($notice['acknowledged_at'])?> UTC.</p><?php elseif($manage&&$notice['active']):?><form method="post" action="v2-action.php"><?php postFields('acknowledge',(int)$notice['id']);?><button type="submit">Kvittér notifikation</button></form><?php endif ?></article><?php endforeach ?><?php if(!$notices):?><section class="panel"><p>Ingen <?=$resolved?'afsluttede':'aktive'?> notifikationer.</p></section><?php endif ?><nav class="pagination"><?php if($f['page']>1):?><a href="<?=h(url(['page'=>$f['page']-1]))?>">← Forrige</a><?php endif ?><span>Side <?=h($f['page'])?></span><?php if($more):?><a href="<?=h(url(['page'=>$f['page']+1]))?>">Næste →</a><?php endif ?></nav>
<?php endif ?>
<?php if($view==='settings'):$storedFlags=db()->query("SELECT name,value FROM inv_settings WHERE name LIKE 'v2_%'")->fetchAll(PDO::FETCH_KEY_PAIR);?>
<section class="panel"><h2>Uafhængige funktioner</h2><form method="post" action="v2-action.php"><?php postFields('settings');?><?php foreach(['enabled'=>'Aktivér version 2','changes'=>'Detaljeret ændringshistorik','licenses'=>'Licensadministration','security'=>'Sikkerhedsstatus','reports'=>'Rapporter og eksport','notifications'=>'Notifikationer i ITSM'] as $key=>$label):?><label><input type="checkbox" name="<?=h($key)?>" value="1" <?=($storedFlags['v2_'.$key]??'0')==='1'?'checked':''?>><?=h($label)?></label><?php endforeach ?><button type="submit">Gem modulindstillinger</button></form><p>Deaktivering skjuler funktionerne og stopper deres behandling. Eksisterende data slettes ikke. Den oprindelige inventarindsamling og browsermodulet har deres egne indstillinger.</p></section>
<?php endif ?><footer>PC Inventory Agent 2.0 · Licensrettigheder er centralt registrerede oplysninger, ikke automatisk bekræftet compliance.</footer></div></main></body></html>
